-- ╭──────────────────────────────────────────────────────────────────────╮
-- │ Generated by `creed theme apply` for mode "{{ mode }}". Do not edit:  │
-- │ put your own settings in ~/.config/hypr/user.lua (loaded last).       │
-- ╰──────────────────────────────────────────────────────────────────────╯

------------------------------ environment ------------------------------
{{ hypr.env }}

------------------------------ monitors --------------------------------
-- Sensible default; override per monitor in user.lua.
hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })

------------------------------ look ------------------------------------
hl.config({
    general = {
        gaps_in = {{ style.window_gaps_in }},
        gaps_out = {{ style.window_gaps_out }},
        border_size = {{ style.window_border }},
        col = {
            active_border = "{{ border.active }}",
            inactive_border = "{{ border.inactive }}",
        },
        resize_on_border = true,
        allow_tearing = {{ hw.tearing }},
        layout = "dwindle",
    },
    decoration = {
        rounding = {{ style.window_rounding }},
        rounding_power = {{ style.rounding_power }},
        active_opacity = 1.0,
        inactive_opacity = 1.0,
        shadow = {
            enabled = {{ shadow.enabled }},
            range = {{ shadow.range }},
            render_power = 3,
            color = "{{ shadow.color }}",
            color_inactive = "{{ shadow.color_inactive }}",
        },
        blur = {
{{ hypr.blur }}
        },
    },
    animations = { enabled = {{ anim.enabled }} },
    input = {
        kb_layout = "{{ input.kb_layout }}",
        follow_mouse = 1,
        sensitivity = 0,
        touchpad = { natural_scroll = {{ input.natural_scroll }}, tap_to_click = true, disable_while_typing = true },
    },
    misc = {
        force_default_wallpaper = 0,
        disable_hyprland_logo = true,
        disable_splash_rendering = true,
        vrr = {{ hw.vrr }},
        focus_on_activate = true,
        middle_click_paste = true,
    },
    cursor = {
        no_hardware_cursors = {{ hw.no_hw_cursors }},
        hide_on_key_press = false,
    },
    binds = { workspace_back_and_forth = false, allow_workspace_cycles = true },
    dwindle = { preserve_split = true },
    ecosystem = { no_update_news = true, no_donation_nag = true },
    xwayland = { force_zero_scaling = true },
})

------------------------------ motion ----------------------------------
{{ hypr.animations }}

------------------------------ shell layers ----------------------------
-- Blur / glass behind Creed's own surfaces. ignore_alpha keeps transparent
-- margins of full-screen popups unblurred.
hl.layer_rule({ name = "creed-glass", match = { namespace = "^creed-(bar|dock|launcher|control|dashboard|notif-center|notifications|clipboard|emoji|power|snap|menu|calendar|osd|widgets)$" }, blur = {{ glass.layers }}, ignore_alpha = 0.02 })
hl.layer_rule({ name = "creed-overview", match = { namespace = "^creed-overview$" }, blur = {{ glass.layers }}, ignore_alpha = 0.6 })
hl.layer_rule({ name = "creed-noanim-osd", match = { namespace = "^creed-(osd|notifications)$" }, no_anim = true })
hl.layer_rule({ name = "creed-wallpaper", match = { namespace = "^creed-(wallpaper|widgets)$" }, no_anim = true })

------------------------------ windows ---------------------------------
hl.window_rule({ name = "creed-suppress-maximize", match = { class = ".*" }, suppress_event = "maximize" })
hl.window_rule({ name = "creed-xwayland-drag-fix", match = { class = "^$", title = "^$", xwayland = true, float = true, fullscreen = false, pin = false }, no_focus = true })
hl.window_rule({ name = "creed-settings", match = { class = "^(creed-settings|org.creed.Settings)$" }, float = true, center = true, size = "980 680" })
hl.window_rule({ name = "creed-dialogs", match = { class = "^(pavucontrol|org.pulseaudio.pavucontrol|blueman-manager|nm-connection-editor|xdg-desktop-portal-gtk)$" }, float = true, center = true })
hl.window_rule({ name = "creed-games-immediate", match = { class = "^(steam_app_.*|gamescope)$" }, immediate = true })
{{? window.float }}
-- Desktop-style windows: everything floats and opens centred.
hl.window_rule({ name = "creed-float-all", match = { class = ".*" }, float = true, center = true })
{{/?}}

------------------------------ titlebars -------------------------------
-- Needs the hyprbars plugin (built by `creed plugins build`, loaded at login).
{{ hypr.titlebars }}

------------------------------ autostart -------------------------------
hl.on("hyprland.start", function()
    hl.exec_cmd("creed-shell")
{{ hypr.autostart }}
end)
